import pandas as pd
import numpy as np

def extract_numeric(s):
    if pd.isna(s): return np.nan
    s = str(s).strip()
    if not s: return np.nan
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')
    if s.count('.') > 1:
        parts = s.split('.')
        s = "".join(parts[:-1]) + "." + parts[-1]

    try:
        return float(s)
    except:
        return np.nan

df = pd.read_csv('/app/dataset/production_FARM_C.csv', encoding='utf-8', skiprows=3, sep=';', dtype=str)
df.columns = df.columns.str.strip()
df = df.loc[:, ~df.columns.duplicated()]

df['reading'] = df['reading'].apply(extract_numeric)
print(df['reading'].max())
print(df[df['reading'] > 800000]['reading'].head())
